        this.selectedTheme = '';
        this.selectedSubTheme = '';
        this.manualTheme = '';
        this.manualSubTheme = '';
        this.availableThemes = [];
        this.availableSubThemes = [];
        this.filteredThemes = [];
        this.filteredSubThemes = [];
        this.themeSearchText = '';
        this.subThemeSearchText = '';
